import {groupVehicleFeatures} from './vehicle-features.js';
import {icon} from './ui-icons.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const number=n=>new Intl.NumberFormat('pt-BR').format(n);
const vehicleUrl=id=>'/veiculo/'+encodeURIComponent(id);
const imageUrl=url=>url.startsWith('assets/')?'/'+url:url;
export function renderVehicleCards(list,{saved=[],compare=[]}={}){return list.map(c=>`<article class="vehicle-card" data-motion-key="${esc(c.id)}"><div class="car-photo"><a href="${vehicleUrl(c.id)}" aria-label="Ver ${esc(c.brand+' '+c.name)}"><img src="${esc(imageUrl(c.images[0]))}" alt="${esc(c.brand+' '+c.name+' '+c.year)}" loading="lazy" decoding="async" width="1200" height="900"></a>${c.badge?`<span class="car-badge">${esc(c.badge)}</span>`:''}<button class="save-car ${saved.includes(c.id)?'saved':''}" data-save="${esc(c.id)}" aria-label="${saved.includes(c.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}">${icon('heart')}</button></div><div class="car-body"><span class="car-brand">${esc(c.brand)}</span><h3><a href="${vehicleUrl(c.id)}">${esc(c.name)}</a></h3><p class="car-version">${esc(c.version)}</p><div class="car-specs"><span>${icon('calendar')} ${c.year}</span><span>${icon('gauge')} ${number(c.km)} km</span><span>${icon('transmission')} ${esc(c.transmission)}</span></div><div class="car-bottom"><strong class="car-price"><small>R$</small> ${number(c.price)}</strong><a class="detail-arrow" href="${vehicleUrl(c.id)}" aria-label="Detalhes de ${esc(c.name)}">${icon('arrow-up-right')}</a></div><label class="compare-label"><input type="checkbox" data-compare="${esc(c.id)}" ${compare.includes(c.id)?'checked':''}> Adicionar à comparação</label></div></article>`).join('')}
export function renderVehicleDetail(c,cars=[],options={}){
const id=c.id,cards=list=>renderVehicleCards(list,options);
const message=`Olá! Tenho interesse no ${c.brand} ${c.name} ${c.version}, ano ${c.year}, anunciado por ${money(c.price)}. Ele está disponível?`;
const url="/whatsapp?"+new URLSearchParams({number:"5547996190693",placement:"veiculo",page:vehicleUrl(id),vehicle:id,text:message});
return `<div class="detail-grid"><div class="vehicle-media"><div class="detail-photo"><img id="detail-image" src="${esc(imageUrl(c.images[0]))}" alt="${esc(c.brand+' '+c.name)} — foto 1" width="1200" height="900" decoding="async" fetchpriority="high"><span class="photo-count" id="photo-count" aria-live="polite">1 / ${c.images.length}</span></div><div class="gallery" role="group" aria-label="Fotos do veículo" tabindex="0">${c.images.map((img,i)=>`<button data-gallery="${esc(imageUrl(img))}" data-image-alt="${esc(c.brand+' '+c.name)} — foto ${i+1}" data-photo-count="${i+1} / ${c.images.length}" aria-pressed="${i===0}" aria-label="Ver foto ${i+1}"><img src="${esc(imageUrl(img))}" alt="" width="120" height="90" loading="lazy" decoding="async"></button>`).join('')}</div><p class="gallery-help">Selecione uma miniatura para ver a foto.</p></div><div class="detail-copy"><span class="eyebrow brand">${esc(c.brand)}</span><h1>${esc(c.name)}</h1><p>${esc(c.version)}</p><strong class="car-price">${money(c.price)}</strong><div class="detail-specs">${[['Ano',c.year],['Quilometragem',number(c.km)+' km'],['Câmbio',c.transmission],['Combustível',c.fuel],['Categoria',c.category]].map(([k,v])=>`<div><small>${k}</small>${esc(v)}</div>`).join('')}</div>${c.description?`<p class="vehicle-description">${esc(c.description)}</p>`:''}<p>Confirme a disponibilidade, as condições e os detalhes com nossa equipe.</p><a data-whatsapp-random class="button dark" data-lead="${esc(c.id)}" href="${esc(url)}" target="_blank" rel="noopener">Tenho interesse <span>${icon('arrow-up-right')}</span></a><a class="button outline" href="/contato">Conhecer pessoalmente ${icon('arrow-up-right')}</a></div></div>${renderVehicleFeatures(c)}<section class="related-vehicles"><h2>Outros caminhos para você.</h2><div class="vehicle-grid">${cards(cars.filter(v=>v.id!==id).slice(0,3))}</div></section>`;
}

export function renderVehicleFeatures(car){
 const groups=groupVehicleFeatures(car.features||[]),total=groups.reduce((count,group)=>count+group.items.length,0);
 if(!total)return '';
 const check='<svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 10 3 3 7-7" stroke-linecap="round" stroke-linejoin="round"/></svg>';
 return '<section class="vehicle-features equipment-section" aria-labelledby="vehicle-features-title"><div class="equipment-heading"><div><span class="eyebrow brand">CADA DETALHE CONTA</span><h2 id="vehicle-features-title">Opcionais e equipamentos</h2><p>Veja o que este '+esc(car.name)+' oferece para o seu dia a dia.</p></div><span class="equipment-total"><strong>'+total+'</strong> '+(total===1?'item equipado':'itens equipados')+'</span></div><div class="equipment-groups">'+groups.map(group=>'<section class="equipment-group"><h3>'+esc(group.name)+'<span>'+group.items.length+'</span></h3><ul>'+group.items.map(label=>'<li><span class="equipment-check">'+check+'</span><span>'+esc(label)+'</span></li>').join('')+'</ul></section>').join('')+'</div></section>';
}
